def merge_two_lists(a, b):
    head = None
    tail = None
    def attach(node):
        nonlocal head, tail
        if head is None:
            head = tail = node
        else:
            tail.next = node
            tail = node
    while a is not None and b is not None:
        if a.value <= b.value:
            attach(a)
            a = a.next
        else:
            attach(b)
            b = b.next
    attach(a if a is not None else b)
    return head

