def merge_two_lists(a, b):
    first = []
    while a is not None:
        first.append(a.value)
        a = a.next
    second = []
    while b is not None:
        second.append(b.value)
        b = b.next
    merged = []
    i = j = 0
    while i < len(first) and j < len(second):
        if first[i] <= second[j]:
            merged.append(first[i])
            i += 1
        else:
            merged.append(second[j])
            j += 1
